<?php use App\Core\Security;?><h4>دسته‌بندی محصولات</h4><form method="post" class="card card-body mb-3"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="row g-2"><div class="col-md-4"><input name="name" class="form-control" placeholder="نام دسته" required></div><div class="col-md-6"><input name="description" class="form-control" placeholder="توضیحات"></div><div class="col-md-2"><button class="btn btn-primary w-100">ثبت</button></div></div></form><table class="table table-bordered"><thead><tr><th>نام</th><th>توضیحات</th><th>وضعیت</th></tr></thead><tbody><?php foreach($categories as $r):?><tr><td><?=Security::e($r['name'])?></td><td><?=Security::e($r['description'])?></td><td><?=$r['is_active']?'فعال':'غیرفعال'?></td></tr><?php endforeach;?></tbody></table>